script:
page.today=new Date();
page.policyApiUrl=page.apiBaseUrl+"/policies";
page.claimApiUrl=page.apiBaseUrl+"/claims";
page.caseServiceUrl=page.apiBaseUrl+"/case-service/cases";
page.policyFetched=false;page.policyLoading=false;page.submitting=false;page.submitted=false;page.submitSuccess=false;page.submitError="";page.submitMessage="";page.validationErrors={};
page.claimantTypes = [
    {label:"Policyholder", value:"POLICYHOLDER"},
    {label:"Driver", value:"DRIVER"},
    {label:"Third Party", value:"THIRD_PARTY"},
    {label:"Representative", value:"REPRESENTATIVE"}
];

page.lossTypes = [
    {label:"Collision", value:"COLLISION"},
    {label:"Theft", value:"THEFT"},
    {label:"Fire", value:"FIRE"},
    {label:"Flood", value:"FLOOD"},
    {label:"Glass", value:"GLASS"},
    {label:"Other", value:"OTHER"}
];

page.licenceStatuses = [
    {label:"Valid", value:"VALID"},
    {label:"Expired", value:"EXPIRED"},
    {label:"Suspended", value:"SUSPENDED"},
    {label:"Unknown", value:"UNKNOWN"}
];

page.yesNoOptions = [
    {label:"Yes", value:"YES"},
    {label:"No", value:"NO"}
];

page.preferredContacts = [
    {label:"Email", value:"EMAIL"},
    {label:"SMS", value:"SMS"},
    {label:"Phone", value:"PHONE"}
];

page.policySearchTypes = [
    { label: "Policy Number", value: "POLICY_NUMBER" },
    { label: "Registration Number", value: "REGISTRATION_NUMBER" },
    { label: "Customer ID", value: "CUSTOMER_ID" }
];
page.searchType = "POLICY_NUMBER";
page.searchTypeLabel = "Policy Number";
page.searchTypePlaceholder = "Enter Policy Number";
page.searchValue = "";
page.searchTypeError = "";
page.searchValueError = "";
page.preferredContactValue = "";
page.preferredContactValueError = "";

const searchType = (
    bh.input.searchType ||
    page.searchType ||
    ""
).toString().trim();

const searchValue = (
    bh.input.searchValue ||
    page.searchValue ||
    ""
).toString().trim();

page.searchType = searchType;
page.searchValue = searchValue;

page.searchTypeError = "";
page.searchValueError = "";
page.policyError = "";
page.policyFetched = false;
page.policyLoading = false;


/* -----------------------------------------
   Validate Search Type
----------------------------------------- */

if (!searchType) {
    page.searchTypeError = "Search Type is required";

}

const validSearchTypes = [
    "POLICY_NUMBER",
    "REGISTRATION_NUMBER",
    "CUSTOMER_ID"
];

if (validSearchTypes.indexOf(searchType) === -1) {
    page.searchTypeError = "Invalid Search Type";

}


/* -----------------------------------------
   Validate Search Value
----------------------------------------- */

if (!searchValue) {

    if (searchType === "POLICY_NUMBER") {
        page.searchValueError = "Policy Number is required";
    }
    else if (searchType === "REGISTRATION_NUMBER") {
        page.searchValueError = "Registration Number is required";
    }
    else if (searchType === "CUSTOMER_ID") {
        page.searchValueError = "Customer ID is required";
    }
    else {
        page.searchValueError = "Search Value is required";
    }


}


/* -----------------------------------------
   Validate Format
----------------------------------------- */

if (searchType === "POLICY_NUMBER") {

    if (!/^[A-Za-z0-9\-/]+$/.test(searchValue)) {
        page.searchValueError = "Enter a valid policy number";

    }

}
else if (searchType === "REGISTRATION_NUMBER") {

    if (!/^[A-Za-z0-9\-/ ]+$/.test(searchValue)) {
        page.searchValueError = "Enter a valid registration number";

    }

}
else if (searchType === "CUSTOMER_ID") {

    if (!/^[A-Za-z0-9\-/]+$/.test(searchValue)) {
        page.searchValueError = "Enter a valid customer ID";

    }

}


/* -----------------------------------------
   Prepare HTTP URL
----------------------------------------- */

page.policyLoading = true;

bh.local.policyApiUrl =
    page.apiBaseUrl +
    "/policies/search" +
    "?searchType=" +
    encodeURIComponent(searchType) +
    "&searchValue=" +
    encodeURIComponent(searchValue);

console.log("Policy Search URL:", bh.local.policyApiUrl);

page.policyLoading = false;

const r = bh.local.response || {};

const policies = Array.isArray(r.policies)
    ? r.policies
    : [];

if (!r.success || policies.length === 0) {
    page.policyFetched = false;
    page.policyError = "Policy not found.";
    return;
}

const p = policies[0];

/* Policy identity */
page.policyId = p.id || "";
page.policyNumber = p.policyNumber || "";
page.customerId = p.customerId || "";

/* Policy details */
page.policyStatus = p.policyStatus || "";
page.policyStartDate = p.policyStartDate || "";
page.policyEndDate = p.policyEndDate || "";
page.insuredName = p.insuredName || "";

/* Vehicle */
page.vehicleRegistration = p.vehicleRegistration || "";
page.vehicleMake = p.vehicleMake || "";
page.vehicleModel = p.vehicleModel || "";
page.vehicleYear = p.vehicleYear || "";

page.vehicleMakeModel =
    [page.vehicleMake, page.vehicleModel]
        .filter(function(v) {
            return v !== null &&
                   v !== undefined &&
                   v !== "";
        })
        .join(" ");

/* Coverage */
page.coverageType = p.coverageType || "";

page.coveredPerils =
    Array.isArray(p.coveredPerils)
        ? p.coveredPerils
        : [];

page.excess = p.excessAmount ?? "";
page.sumInsured = p.sumInsured ?? "";
page.currency = p.currency || "INR";

/* Success */
page.policyFetched = true;
page.policyError = "";

const f=bh.input.fieldName,v=page[f],s=v==null?"":v.toString().trim();let e="";
if(f==="policyNumber"&&!s)e="Policy Number is required";
else if(f==="claimantType"&&!s)e="Claimant Type is required";
else if(f==="lossDate"){if(!s)e="Loss Date & Time is required";else if(new Date(s)>new Date())e="Loss Date & Time cannot be in the future";else if(page.policyFetched&&page.policyStartDate&&page.policyEndDate&&(new Date(s)<new Date(page.policyStartDate)||new Date(s)>new Date(page.policyEndDate)))e="Loss Date & Time must be within the policy period";}
else if(f==="lossLocation"&&!s)e="Loss Location is required";
else if(f==="lossType"&&!s)e="Loss Type is required";
else if(f==="lossDescription"&&(!s||s.length<20))e="Loss Description must contain at least 20 characters";
else if(f==="driverName"&&!s)e="Driver Name is required";
else if(["licenceStatus","vehicleDrivable","thirdPartyFlag","injuryFlag","policeReportAvailable","repairEstimateAvailable","preferredContact"].includes(f)&&!s)e="This field is required";
else if(f==="policeReportReference"&&page.policeReportAvailable==="YES"&&!s)e="Police / FIR reference is required";
else if(f==="estimatedAmount"&&!(Number(v)>0))e="Estimated Repair / Loss Amount must be greater than 0";
page[f+"Error"]=e;page.validationErrors[f]=e;

page.submitted = false;
page.submitError = "";
page.submitSuccess = false;

if (!page.validationErrors) {
    page.validationErrors = {};
}

page.validationErrors = {};

let valid = true;

function setError(field, message) {

    page[field + "Error"] = message || "";
    page.validationErrors[field] = message || "";

    if (message) {
        valid = false;
    }
}


/* Clear previous errors */

const fields = [
    "policyNumber",
    "claimantType",
    "lossDate",
    "lossLocation",
    "lossType",
    "lossDescription",
    "driverName",
    "licenceStatus",
    "vehicleDrivable",
    "thirdPartyFlag",
    "injuryFlag",
    "policeReportAvailable",
    "policeReportReference",
    "estimatedAmount",
    "preferredContact",
    "preferredContactValue"
];

fields.forEach(function(field) {
    page[field + "Error"] = "";
});


/* Policy */

const policyNumber =
    (page.policyNumber || "").toString().trim();

if (!policyNumber) {

    setError(
        "policyNumber",
        "Policy Number is required"
    );

}
else if (!page.policyFetched || !page.policyId) {

    setError(
        "policyNumber",
        "Fetch a valid policy before submitting"
    );

}


/* Claimant */

const claimantType =
    (page.claimantType || "").toString().trim();

const validClaimantTypes = [
    "POLICYHOLDER",
    "DRIVER",
    "THIRD_PARTY",
    "REPRESENTATIVE"
];

if (!claimantType) {

    setError(
        "claimantType",
        "Claimant Type is required"
    );

}
else if (
    validClaimantTypes.indexOf(claimantType) === -1
) {

    setError(
        "claimantType",
        "Select a valid Claimant Type"
    );

}


/* Loss Date */

if (!page.lossDate) {

    setError(
        "lossDate",
        "Loss Date & Time is required"
    );

}
else {

    const lossDate = new Date(page.lossDate);

    if (isNaN(lossDate.getTime())) {

        setError(
            "lossDate",
            "Enter a valid Loss Date & Time"
        );

    }
    else if (lossDate > new Date()) {

        setError(
            "lossDate",
            "Loss Date & Time cannot be in the future"
        );

    }
    else if (
        page.policyStartDate &&
        page.policyEndDate &&
        (
            lossDate < new Date(page.policyStartDate) ||
            lossDate > new Date(page.policyEndDate)
        )
    ) {

        setError(
            "lossDate",
            "Loss Date & Time must be within the policy period"
        );

    }

}


/* Loss Location */

if (!(page.lossLocation || "").toString().trim()) {

    setError(
        "lossLocation",
        "Loss Location is required"
    );

}


/* Loss Type */

const validLossTypes = [
    "COLLISION",
    "THEFT",
    "FIRE",
    "FLOOD",
    "GLASS",
    "OTHER"
];

if (!page.lossType) {

    setError(
        "lossType",
        "Loss Type is required"
    );

}
else if (
    validLossTypes.indexOf(page.lossType) === -1
) {

    setError(
        "lossType",
        "Select a valid Loss Type"
    );

}


/* Loss Description */

const description =
    (page.lossDescription || "").toString().trim();

if (!description) {

    setError(
        "lossDescription",
        "Loss Description is required"
    );

}
else if (description.length < 20) {

    setError(
        "lossDescription",
        "Loss Description must contain at least 20 characters"
    );

}


/* Driver */

if (!(page.driverName || "").toString().trim()) {

    setError(
        "driverName",
        "Driver Name is required"
    );

}


/* Licence */

const validLicenceStatuses = [
    "VALID",
    "EXPIRED",
    "SUSPENDED",
    "UNKNOWN"
];

if (!page.licenceStatus) {

    setError(
        "licenceStatus",
        "Licence Status is required"
    );

}
else if (
    validLicenceStatuses.indexOf(page.licenceStatus) === -1
) {

    setError(
        "licenceStatus",
        "Select a valid Licence Status"
    );

}


/* Yes / No fields */

const yesNoFields = [
    "vehicleDrivable",
    "thirdPartyFlag",
    "injuryFlag",
    "policeReportAvailable"
];

yesNoFields.forEach(function(field) {

    if (
        page[field] !== "YES" &&
        page[field] !== "NO"
    ) {

        setError(
            field,
            "Select Yes or No"
        );

    }

});


/* Police reference */

if (page.policeReportAvailable === "YES") {

    if (
        !(page.policeReportReference || "")
            .toString()
            .trim()
    ) {

        setError(
            "policeReportReference",
            "Police / FIR reference is required"
        );

    }

}
else {

    page.policeReportReference = "";

}


/* Estimated Amount */

const amount =
    Number(page.estimatedAmount);

if (
    page.estimatedAmount === null ||
    page.estimatedAmount === undefined ||
    page.estimatedAmount === ""
) {

    setError(
        "estimatedAmount",
        "Estimated Loss Amount is required"
    );

}
else if (!isFinite(amount) || amount <= 0) {

    setError(
        "estimatedAmount",
        "Estimated Loss Amount must be greater than 0"
    );

}


/* Preferred Contact */

const validContacts = [
    "EMAIL",
    "SMS",
    "PHONE"
];

if (!page.preferredContact) {

    setError(
        "preferredContact",
        "Preferred Contact is required"
    );

}
else if (
    validContacts.indexOf(page.preferredContact) === -1
) {

    setError(
        "preferredContact",
        "Select a valid Preferred Contact"
    );

}


/* Preferred Contact Value */

const contactValue =
    (page.preferredContactValue || "")
        .toString()
        .trim();

if (!contactValue) {

    setError(
        "preferredContactValue",
        "Preferred Contact Value is required"
    );

}
else if (page.preferredContact === "PHONE" ||
         page.preferredContact === "SMS") {

    if (!/^[0-9]{10}$/.test(contactValue)) {

        setError(
            "preferredContactValue",
            "Enter a valid 10-digit mobile number"
        );

    }

}
else if (page.preferredContact === "EMAIL") {

    if (
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactValue)
    ) {

        setError(
            "preferredContactValue",
            "Enter a valid email address"
        );

    }

}


/* Final */

bh.local.isValid = valid;

if (!valid) {

    page.submitError =
        "Please correct the highlighted fields before submitting.";

    page.submitting = false;

}

console.log('claim form is valid', bh.local.isValid);
/* Validation successful */

page.submitted = true;
page.submitting = true;
page.submitError = "";

console.log("========== CLAIM RESPONSE ==========");
console.log("Claim Response:", bh.local.response);

page.submitting = false;
page.submitSuccess = false;
page.submitMessage = "";

const r = bh.local.response || {};

/* =========================================================
   API FAILURE
   ========================================================= */

if (!r.success) {

    page.submitSuccess = false;

    page.submitMessage =
        r.message ||
        "Claim submission failed.";

    console.error(
        "Claim submission failed:",
        r
    );

}else {

/* =========================================================
   CLAIM RESPONSE
   ========================================================= */

const claim = r.claim || {};
const evidence = r.evidence || {};

/* =========================================================
   CLAIM DETAILS
   ========================================================= */

page.claimId =
    claim.claimId || "";

page.claimNumber =
    claim.claimNumber || "";

page.claimPolicyId =
    claim.policyId || page.policyId || "";

page.claimStatus =
    claim.status || "";

page.claimCreatedAt =
    claim.createdAt || "";

/* =========================================================
   EVIDENCE DETAILS
   ========================================================= */

page.evidenceTotal =
    Number(evidence.total || 0);

page.evidenceUploaded =
    Number(evidence.uploaded || 0);

page.evidenceFailed =
    Number(evidence.failed || 0);

/* =========================================================
   SUCCESS
   ========================================================= */

page.submitSuccess = true;
page.submitMessage = "Claim submitted successfully.";

console.log("Claim submitted successfully.");
console.log("Claim ID:", page.claimId);
console.log("Claim Number:", page.claimNumber);
console.log("Claim Status:", page.claimStatus);
console.log("Created At:", page.claimCreatedAt);

console.log("Evidence Total:", page.evidenceTotal);
console.log("Evidence Uploaded:", page.evidenceUploaded);
console.log("Evidence Failed:", page.evidenceFailed);

console.log("====================================");
}

const type = page.searchType;

if (type === "POLICY_NUMBER") {
    page.searchTypeLabel = "Policy Number";
    page.searchTypePlaceholder = "Enter Policy Number";
}
else if (type === "REGISTRATION_NUMBER") {
    page.searchTypeLabel = "Registration Number";
    page.searchTypePlaceholder = "Enter Registration Number";
}
else if (type === "CUSTOMER_ID") {
    page.searchTypeLabel = "Customer ID";
    page.searchTypePlaceholder = "Enter Customer ID";
}

page.searchValue = "";
page.searchError = "";
page.policyFetched = false;
